const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');

const app = express();
app.use(express.json({ limit: '1mb' }));

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Key management for token verification - supports key rotation
const KEY_STORE = {
  'key-001': Buffer.from(process.env.SIGNING_KEY_1 || crypto.randomBytes(32).toString('hex'), 'hex'),
  'key-002': Buffer.from(process.env.SIGNING_KEY_2 || crypto.randomBytes(32).toString('hex'), 'hex'),
};

// Utility: deep merge for configuration objects
function deepMerge(target, source) {
  for (const key of Object.keys(source)) {
    if (source[key] && typeof source[key] === 'object' && !Buffer.isBuffer(source[key])) {
      if (!target[key] || typeof target[key] !== 'object') {
        target[key] = {};
      }
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

// Token creation with HMAC-SHA256
function createToken(payload, keyId = 'key-001') {
  const header = Buffer.from(JSON.stringify({ alg: 'HS256', kid: keyId })).toString('base64url');
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const signingKey = KEY_STORE[keyId];
  const signature = crypto.createHmac('sha256', signingKey)
    .update(`${header}.${body}`)
    .digest('base64url');
  return `${header}.${body}.${signature}`;
}

// Token verification
function verifyToken(token) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Invalid token format');

  const [headerB64, bodyB64, signatureB64] = parts;
  const header = JSON.parse(Buffer.from(headerB64, 'base64url').toString());

  if (header.alg !== 'HS256') throw new Error('Unsupported algorithm');

  const keyId = header.kid;
  const signingKey = KEY_STORE[keyId];

  if (!signingKey) throw new Error('Unknown signing key');

  const expectedSig = crypto.createHmac('sha256', signingKey)
    .update(`${headerB64}.${bodyB64}`)
    .digest('base64url');

  if (!crypto.timingSafeEqual(Buffer.from(signatureB64), Buffer.from(expectedSig))) {
    throw new Error('Invalid signature');
  }

  const payload = JSON.parse(Buffer.from(bodyB64, 'base64url').toString());

  if (payload.exp && Date.now() > payload.exp * 1000) {
    throw new Error('Token expired');
  }

  return payload;
}

// Auth middleware
function authMiddleware(req, res, next) {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing authorization' });
    }
    req.user = verifyToken(authHeader.slice(7));
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Authentication failed' });
  }
}

// User preferences endpoint - allows deep merge of settings
app.put('/api/v1/users/:userId/preferences', authMiddleware, async (req, res) => {
  try {
    const { userId } = req.params;

    if (req.user.sub !== userId && req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Forbidden' });
    }

    // Validate preferences is an object
    if (!req.body.preferences || typeof req.body.preferences !== 'object' || Array.isArray(req.body.preferences)) {
      return res.status(400).json({ error: 'Invalid preferences format' });
    }

    // Get current preferences
    const result = await pool.query(
      'SELECT preferences FROM user_settings WHERE user_id = $1',
      [userId]
    );

    let currentPrefs = result.rows.length > 0 ? result.rows[0].preferences : {};

    // Deep merge new preferences with existing ones
    const mergedPrefs = deepMerge(currentPrefs, req.body.preferences);

    await pool.query(
      `INSERT INTO user_settings (user_id, preferences, updated_at)
       VALUES ($1, $2, NOW())
       ON CONFLICT (user_id) DO UPDATE SET preferences = $2, updated_at = NOW()`,
      [userId, JSON.stringify(mergedPrefs)]
    );

    return res.json({ preferences: mergedPrefs });
  } catch (err) {
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Admin endpoint to configure application settings
app.post('/api/v1/admin/config', authMiddleware, async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Admin access required' });
    }

    const { section, settings } = req.body;

    if (!section || typeof section !== 'string' || !settings || typeof settings !== 'object') {
      return res.status(400).json({ error: 'Invalid config format' });
    }

    // Sanitize section name
    if (!/^[a-zA-Z0-9_-]+$/.test(section)) {
      return res.status(400).json({ error: 'Invalid section name' });
    }

    await pool.query(
      `INSERT INTO app_config (section, settings, updated_by, updated_at)
       VALUES ($1, $2, $3, NOW())
       ON CONFLICT (section) DO UPDATE SET settings = $2, updated_by = $3, updated_at = NOW()`,
      [section, JSON.stringify(settings), req.user.sub]
    );

    return res.json({ success: true });
  } catch (err) {
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Public registration endpoint
app.post('/api/v1/auth/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;

    if (!username || !email || !password) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    if (typeof username !== 'string' || username.length < 3 || username.length > 30) {
      return res.status(400).json({ error: 'Invalid username' });
    }

    if (!/^[a-zA-Z0-9_]+$/.test(username)) {
      return res.status(400).json({ error: 'Username must be alphanumeric' });
    }

    if (typeof password !== 'string' || password.length < 12 || password.length > 128) {
      return res.status(400).json({ error: 'Password must be 12-128 characters' });
    }

    const salt = crypto.randomBytes(16).toString('hex');
    const hash = crypto.scryptSync(password, salt, 64).toString('hex');

    const result = await pool.query(
      `INSERT INTO users (username, email, password_hash, salt, role, created_at)
       VALUES ($1, $2, $3, $4, 'user', NOW()) RETURNING id`,
      [username, email, hash, salt]
    );

    const token = createToken({
      sub: result.rows[0].id,
      username,
      role: 'user',
      exp: Math.floor(Date.now() / 1000) + 3600
    });

    return res.status(201).json({ token, userId: result.rows[0].id });
  } catch (err) {
    if (err.code === '23505') {
      return res.status(409).json({ error: 'Username or email already exists' });
    }
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Login endpoint
app.post('/api/v1/auth/login', async (req, res) => {
  try {
    const { username, password } = req.body;

    if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid credentials format' });
    }

    const result = await pool.query(
      'SELECT id, username, password_hash, salt, role FROM users WHERE username = $1',
      [username.toLowerCase()]
    );

    if (result.rows.length === 0) {
      // Constant-time dummy computation to prevent timing attacks
      crypto.scryptSync('dummy', 'dummy-salt-value', 64);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];
    const computedHash = crypto.scryptSync(password, user.salt, 64).toString('hex');

    if (!crypto.timingSafeEqual(Buffer.from(computedHash, 'hex'), Buffer.from(user.password_hash, 'hex'))) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = createToken({
      sub: user.id,
      username: user.username,
      role: user.role,
      exp: Math.floor(Date.now() / 1000) + 3600
    });

    return res.json({ token });
  } catch (err) {
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Get user profile
app.get('/api/v1/users/:userId/profile', authMiddleware, async (req, res) => {
  try {
    const { userId } = req.params;

    const result = await pool.query(
      'SELECT id, username, email, role, created_at FROM users WHERE id = $1',
      [userId]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Only return email to self or admin
    const profile = result.rows[0];
    if (req.user.sub !== userId && req.user.role !== 'admin') {
      delete profile.email;
    }

    return res.json({ profile });
  } catch (err) {
    return res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = app;
